#!/bin/bash
# ============================================================================
# fix_surgery_dashboard_infinite_loading.sh
#
# Fixes: Surgery Dashboard stuck showing "Loading..." with no data and no
# visible error.
#
# ROOT CAUSE: getSurgeryDashboardScheduled/Active/History (in
# doctor-dashboard-surgery/actions.js) returned bare arrays and could throw
# on an unexpected query result (e.g. the untested embedded
# recovery_episodes(...) join inside the Active-tab query). A Server Action
# that throws leaves the client's Promise.all() permanently unsettled --
# React never gets a resolved or rejected result, so setLoading(false)
# never runs and the page sits on "Loading..." forever with nothing printed
# to the console to explain why.
#
# FIX: Every action now wraps its query in try/catch and always returns a
# plain { rows, error } object instead of throwing or returning a bare
# array. page.js now reads .rows/.error from each result, always calls
# setLoading(false) in a finally block, and surfaces any error message in
# a banner at the top of the dashboard instead of hanging silently.
#
#   MODIFIED: app/(main)/doctor-dashboard-surgery/actions.js
#   MODIFIED: app/(main)/doctor-dashboard-surgery/page.js
#
# Run this from the root of your veda-hmis repo in GitHub Codespaces.
# ============================================================================

set -e

echo "==> Surgery Dashboard infinite-loading fix"
echo ""

if [ ! -f "package.json" ] || [ ! -d "app" ]; then
  echo "ERROR: This doesn't look like the veda-hmis repo root (no package.json / app dir found)."
  echo "cd into your repo root and re-run this script."
  exit 1
fi

if [ ! -d "app/(main)/doctor-dashboard-surgery" ]; then
  echo "ERROR: app/(main)/doctor-dashboard-surgery not found."
  echo "This script expects the Surgery Dashboard to already exist (from add_doctor_surgery_dashboard.sh)."
  exit 1
fi

echo "==> Overwriting app/(main)/doctor-dashboard-surgery/actions.js"
echo "" | base64 -d > "app/(main)/doctor-dashboard-surgery/actions.js"

echo "==> Overwriting app/(main)/doctor-dashboard-surgery/page.js"
echo "" | base64 -d > "app/(main)/doctor-dashboard-surgery/page.js"

echo ""
echo "==> Files written. Verifying build..."
if command -v npm >/dev/null 2>&1; then
  npm run build || { echo "BUILD FAILED -- check output above before pushing."; exit 1; }
else
  echo "npm not found -- skipping build verification, run 'npm run build' manually."
fi

echo ""
echo "==> Done. Review changes with: git status && git diff"
echo "==> To deploy, run:"
echo "    git add -A"
echo '    git commit -m "Fix Surgery Dashboard infinite loading -- Server Actions now return {rows,error} and always resolve instead of hanging"'
echo "    git push"
